/**
 * @license MIT
 * Lyrics for the Focus Mode beds.
 *
 * These are **original lines written for this course**, not transcriptions of
 * any commercial song. Arijit Singh's recordings (and every slowed+reverb
 * version of them) are copyrighted — shipping them would get the app taken
 * down, and no "royalty free" label on a reupload makes that legal. So the
 * player ships its own Hindi-lofi playlist: five beds generated by
 * `scripts/make-focus-audio.py` with lyrics written to match each mood,
 * with emoji, timed to the beat of that bed.
 *
 * Each line is `{ at: seconds into the track, en, hi }`. The player shows the
 * line whose `at` is the latest one passed, so scrubbing and looping always
 * land on the right line.
 */
export interface LyricLine {
  /** Seconds from the start of that track. */
  at: number;
  /** Roman Hinglish — what the student sings along to. */
  en: string;
  /** Devanagari, for students who read Hindi. */
  hi: string;
}

export interface TrackLyrics {
  /** Shown above the lines, e.g. the "mood" of the track. */
  title: string;
  lines: LyricLine[];
}

